-- Original practice exercises for the catalog. No external task bank is required.
BEGIN;

INSERT INTO public.subjects (code, name)
VALUES
    ('emath', 'ЕГЭ Математика'),
    ('omath', 'ОГЭ Математика'),
    ('ephysic', 'ЕГЭ Физика'),
    ('ophysic', 'ОГЭ Физика')
ON CONFLICT (code) DO NOTHING;

WITH topic_seed (subject_code, number, name) AS (
  VALUES
    ('emath', 1, 'Уравнения'),
    ('emath', 2, 'Производная и исследование функций'),
    ('emath', 3, 'Вероятность'),
    ('omath', 1, 'Числа и вычисления'),
    ('omath', 2, 'Проценты и пропорции'),
    ('omath', 3, 'Геометрия на плоскости'),
    ('ephysic', 1, 'Кинематика'),
    ('ephysic', 2, 'Динамика и законы сохранения'),
    ('ephysic', 3, 'Электрические цепи'),
    ('ophysic', 1, 'Скорость и путь'),
    ('ophysic', 2, 'Давление и плотность'),
    ('ophysic', 3, 'Тепловые явления')
), inserted_topics AS (
  INSERT INTO public.topics (subject_code, number, name)
  SELECT seed.subject_code, seed.number, seed.name
  FROM topic_seed AS seed
  WHERE NOT EXISTS (
    SELECT 1 FROM public.topics AS existing
    WHERE existing.subject_code = seed.subject_code AND existing.name = seed.name
  )
  RETURNING id, subject_code, name
), catalog_topics AS (
  SELECT id, subject_code, name FROM inserted_topics
  UNION ALL
  SELECT min(existing.id), existing.subject_code, existing.name
  FROM public.topics AS existing
  JOIN topic_seed AS seed ON seed.subject_code = existing.subject_code AND seed.name = existing.name
  GROUP BY existing.subject_code, existing.name
), task_seed (subject_code, topic_name, content, solution, correct_answer, difficulty, points) AS (
  VALUES
    ('emath', 'Уравнения', 'Решите уравнение $4x-11=17$.', 'Прибавим $11$ к обеим частям: $4x=28$. Значит, $x=7$.', '7', 'easy', 1),
    ('emath', 'Уравнения', 'Решите уравнение $3^{2x-1}=81$.', 'Так как $81=3^4$, получаем $2x-1=4$, откуда $x=2{,}5$.', '2.5', 'medium', 2),
    ('emath', 'Уравнения', 'Найдите больший корень уравнения $x^2-9x+14=0$.', 'Разложим на множители: $(x-2)(x-7)=0$. Корни равны $2$ и $7$, больший — $7$.', '7', 'hard', 3),
    ('emath', 'Производная и исследование функций', 'Найдите значение производной $f(x)=x^2+3x$ в точке $x=2$.', '$f''(x)=2x+3$, поэтому $f''(2)=7$.', '7', 'easy', 1),
    ('emath', 'Производная и исследование функций', 'Найдите точку минимума функции $f(x)=2x^2-12x+7$. Укажите значение $x$.', '$f''(x)=4x-12$. Производная меняет знак с минуса на плюс в точке $x=3$.', '3', 'medium', 2),
    ('emath', 'Производная и исследование функций', 'Найдите наибольшее значение функции $f(x)=x^3-3x$ на отрезке $[-2;1]$.', '$f''(x)=3(x^2-1)$. Проверим $x=-2,-1,1$: значения равны $-2,2,-2$. Максимум равен $2$.', '2', 'hard', 3),
    ('emath', 'Вероятность', 'В коробке лежат 7 белых и 3 синих шара. Найдите вероятность достать один синий шар.', 'Из 10 равновозможных исходов благоприятны 3. Вероятность равна $3/10=0{,}3$.', '0.3', 'easy', 1),
    ('emath', 'Вероятность', 'В двух независимых попытках вероятность успеха в каждой равна $0{,}4$. Найдите вероятность хотя бы одного успеха.', 'Вероятность двух неудач равна $0{,}6^2=0{,}36$. Тогда вероятность хотя бы одного успеха равна $1-0{,}36=0{,}64$.', '0.64', 'medium', 2),
    ('emath', 'Вероятность', 'Из коробки с 6 белыми и 4 синими шарами достают два шара без возвращения. Найдите вероятность того, что оба белые. Укажите дробь в формате `a/b`.', 'Вероятность равна $(6/10)\cdot(5/9)=1/3$.', '1/3', 'hard', 3),
    ('omath', 'Числа и вычисления', 'Вычислите $17-3\cdot4$.', 'Сначала умножаем: $3\cdot4=12$. Затем вычитаем: $17-12=5$.', '5', 'easy', 1),
    ('omath', 'Числа и вычисления', 'Найдите значение выражения $\dfrac{3}{4}+\dfrac{7}{20}$.', 'Приведём к знаменателю $20$: $15/20+7/20=22/20=1{,}1$.', '1.1', 'medium', 2),
    ('omath', 'Числа и вычисления', 'Вычислите $(-2)^4-3^2+\sqrt{81}$.', '$(-2)^4=16$, $3^2=9$, $\sqrt{81}=9$. Получаем $16-9+9=16$.', '16', 'hard', 3),
    ('omath', 'Проценты и пропорции', 'Найдите 15% от 240.', 'Умножаем $240$ на $0{,}15$ и получаем $36$.', '36', 'easy', 1),
    ('omath', 'Проценты и пропорции', 'Тетрадь стоила 80 рублей. После скидки 25% сколько рублей она стоит?', 'После скидки остаётся 75% цены: $80\cdot0{,}75=60$ рублей.', '60', 'medium', 2),
    ('omath', 'Проценты и пропорции', 'После повышения цены на 20% рюкзак стоит 1440 рублей. Сколько рублей он стоил до повышения?', 'Новая цена составляет 120% прежней. Делим $1440$ на $1{,}2$ и получаем $1200$ рублей.', '1200', 'hard', 3),
    ('omath', 'Геометрия на плоскости', 'Стороны прямоугольника равны 7 и 9 см. Найдите площадь в квадратных сантиметрах.', '$S=7\cdot9=63$ см².', '63', 'easy', 1),
    ('omath', 'Геометрия на плоскости', 'Катеты прямоугольного треугольника равны 5 и 12 см. Найдите гипотенузу в сантиметрах.', 'По теореме Пифагора $c=\sqrt{5^2+12^2}=\sqrt{169}=13$ см.', '13', 'medium', 2),
    ('omath', 'Геометрия на плоскости', 'Основания трапеции равны 8 и 14 см, высота равна 5 см. Найдите площадь в квадратных сантиметрах.', 'Умножаем полусумму оснований на высоту: $S=(8+14)\cdot5/2=55$ см².', '55', 'hard', 3),
    ('ephysic', 'Кинематика', 'Скорость тела за 3 с равномерно выросла с 4 до 16 м/с. Найдите ускорение в м/с².', '$a=(16-4)/3=4$ м/с².', '4', 'easy', 1),
    ('ephysic', 'Кинематика', 'Тело начало движение из покоя с ускорением 2 м/с². Какой путь в метрах оно прошло за 5 с?', '$s=at^2/2=2\cdot25/2=25$ м.', '25', 'medium', 2),
    ('ephysic', 'Кинематика', 'Автомобиль движется со скоростью 24 м/с и равномерно тормозит с ускорением по модулю 4 м/с². Найдите тормозной путь в метрах.', 'Время остановки равно $24/4=6$ с. Средняя скорость при торможении равна $12$ м/с, путь равен $12\cdot6=72$ м.', '72', 'hard', 3),
    ('ephysic', 'Динамика и законы сохранения', 'На тело массой 3 кг действует равнодействующая сила 18 Н. Найдите ускорение в м/с².', 'По второму закону Ньютона $a=F/m=18/3=6$ м/с².', '6', 'easy', 1),
    ('ephysic', 'Динамика и законы сохранения', 'Тело массой 2 кг движется со скоростью 5 м/с. Найдите его кинетическую энергию в джоулях.', '$E_k=mv^2/2=2\cdot25/2=25$ Дж.', '25', 'medium', 2),
    ('ephysic', 'Динамика и законы сохранения', 'Тележка массой 2 кг со скоростью 6 м/с сцепляется с неподвижной тележкой массой 4 кг. Найдите их общую скорость в м/с.', 'Импульс сохраняется: $2\cdot6=(2+4)v$. Следовательно, $v=2$ м/с.', '2', 'hard', 3),
    ('ephysic', 'Электрические цепи', 'На резисторе сопротивлением 8 Ом напряжение 12 В. Найдите силу тока в амперах.', 'По закону Ома $I=U/R=12/8=1{,}5$ А.', '1.5', 'easy', 1),
    ('ephysic', 'Электрические цепи', 'Два резистора сопротивлениями 6 и 3 Ом соединены параллельно. Найдите общее сопротивление в омах.', '$1/R=1/6+1/3=1/2$, значит, $R=2$ Ом.', '2', 'medium', 2),
    ('ephysic', 'Электрические цепи', 'Через резистор сопротивлением 5 Ом проходит постоянный ток 2 А. Сколько теплоты в джоулях выделится за 30 с?', 'По закону Джоуля — Ленца $Q=I^2Rt=4\cdot5\cdot30=600$ Дж.', '600', 'hard', 3),
    ('ophysic', 'Скорость и путь', 'Пешеход прошёл 180 м за 120 с. Найдите среднюю скорость в м/с.', '$v=s/t=180/120=1{,}5$ м/с.', '1.5', 'easy', 1),
    ('ophysic', 'Скорость и путь', 'Велосипедист движется со скоростью 18 км/ч. Выразите эту скорость в м/с.', 'Чтобы перевести км/ч в м/с, делим на $3{,}6$: $18/3{,}6=5$.', '5', 'medium', 2),
    ('ophysic', 'Скорость и путь', 'Первую половину пути турист шёл со скоростью 3 км/ч, вторую — со скоростью 6 км/ч. Найдите среднюю скорость за весь путь в км/ч.', 'Для двух равных участков по $s$ км общее время равно $s/3+s/6=s/2$. Средняя скорость равна $2s/(s/2)=4$ км/ч.', '4', 'hard', 3),
    ('ophysic', 'Давление и плотность', 'Сила 60 Н действует перпендикулярно площадке площадью 0,2 м². Найдите давление в паскалях.', '$p=F/S=60/0{,}2=300$ Па.', '300', 'easy', 1),
    ('ophysic', 'Давление и плотность', 'Объём тела равен 200 см³, масса равна 540 г. Найдите плотность в г/см³.', '$\rho=m/V=540/200=2{,}7$ г/см³.', '2.7', 'medium', 2),
    ('ophysic', 'Давление и плотность', 'На глубине 0,8 м в воде найдите давление, создаваемое водой, в паскалях. Плотность воды 1000 кг/м³, $g=10$ м/с².', '$p=\rho gh=1000\cdot10\cdot0{,}8=8000$ Па.', '8000', 'hard', 3),
    ('ophysic', 'Тепловые явления', 'Вода нагрелась с 18 °C до 42 °C. На сколько градусов повысилась температура?', '$42-18=24$ °C.', '24', 'easy', 1),
    ('ophysic', 'Тепловые явления', 'Найдите количество теплоты в джоулях, необходимое для нагревания 0,5 кг воды на 4 °C. Удельная теплоёмкость воды 4200 Дж/(кг·°C).', '$Q=cm\Delta T=4200\cdot0{,}5\cdot4=8400$ Дж.', '8400', 'medium', 2),
    ('ophysic', 'Тепловые явления', 'Смешали 200 г воды при 20 °C и 300 г воды при 60 °C. Теплопотерь нет. Найдите установившуюся температуру в °C.', 'Теплоёмкость воды одинакова. Взвешиваем температуры по массам: $(200\cdot20+300\cdot60)/500=44$ °C.', '44', 'hard', 3)
)
INSERT INTO public.tasks (topic_id, content, solution, correct_answer, difficulty, points, exam_type, answer_format)
SELECT topic.id, seed.content, seed.solution, seed.correct_answer, seed.difficulty, seed.points,
  CASE WHEN left(seed.subject_code, 1) = 'e' THEN 'ege' ELSE 'oge' END,
  'text'
FROM task_seed AS seed
JOIN catalog_topics AS topic ON topic.subject_code = seed.subject_code AND topic.name = seed.topic_name
WHERE NOT EXISTS (
  SELECT 1 FROM public.tasks AS existing
  WHERE existing.topic_id = topic.id AND existing.content = seed.content
);

COMMIT;
